private val bg=Color(0xFF090912); private val panel=Color(0xFF171625); private val violet=Color(0xFF8B35FF); private val ink=Color(0xFFF5F2FF); private val muted=Color(0xFF9B98B5); private val green=Color(0xFF49E38B)
data class Phone(val id:Int,val name:String,val condition:Int,val buy:Int,val market:Int,val color:Int,val fixed:Boolean=false)
data class Listing(val name:String,val condition:Int,val price:Int,val market:Int,val color:Int)
private val catalog=listOf(Listing("Volt V8",88,18500,26900,0xFF6D44D9.toInt()),Listing("Nova X",94,32200,44900,0xFF167EBD.toInt()),Listing("Pulse 12",79,12400,19900,0xFF2B9B88.toInt()),Listing("Phantom Pro",91,41800,57900,0xFFB34B9A.toInt()),Listing("Titan Max",85,27600,38900,0xFFB66A31.toInt()),Listing("Orbit Mini",96,9900,15900,0xFF6476C8.toInt()),Listing("Astra Z",72,16800,24900,0xFF3D9BB1.toInt()),Listing("Zenith 5",90,23800,33900,0xFF927A3A.toInt()))
class MainActivity:ComponentActivity(){override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);val p=getSharedPreferences("phone_flipper",MODE_PRIVATE);setContent{Game(p.getString("save",null)){p.edit().putString("save",it).apply()}}}}
@Composable private fun Game(saved:String?,save:(String)->Unit){
 var money by remember{mutableIntStateOf(42000)};var level by remember{mutableIntStateOf(1)};var xp by remember{mutableIntStateOf(0)};var sold by remember{mutableIntStateOf(0)};var repairs by remember{mutableIntStateOf(0)}
 var stock by remember{mutableStateOf(listOf<Phone>())};var listings by remember{mutableStateOf(catalog.take(4))};var tab by remember{mutableStateOf("Главная")};var selected by remember{mutableStateOf<Phone?>(null)};var checked by remember{mutableStateOf(setOf<String>())};var note by remember{mutableStateOf("Добро пожаловать! Найди выгодный телефон.")}
 fun persist(){val j=JSONObject().put("money",money).put("level",level).put("xp",xp).put("sold",sold).put("repairs",repairs);val a=JSONArray();stock.forEach{a.put(JSONObject().put("id",it.id).put("name",it.name).put("condition",it.condition).put("buy",it.buy).put("market",it.market).put("color",it.color).put("fixed",it.fixed))};j.put("stock",a);save(j.toString())}
 LaunchedEffect(saved){if(!saved.isNullOrBlank())try{val j=JSONObject(saved);money=j.optInt("money",42000);level=j.optInt("level",1);xp=j.optInt("xp",0);sold=j.optInt("sold",0);repairs=j.optInt("repairs",0);val a=j.optJSONArray("stock")?:JSONArray();stock=(0 until a.length()).mapNotNull{val q=a.optJSONObject(it)?:return@mapNotNull null;Phone(q.optInt("id"),q.optString("name"),q.optInt("condition"),q.optInt("buy"),q.optInt("market"),q.optInt("color"),q.optBoolean("fixed"))}}catch(_:Exception){}}
 MaterialTheme(colorScheme=darkColorScheme(primary=violet,background=bg,surface=panel,onSurface=ink)){Scaffold(containerColor=bg,bottomBar={NavigationBar(containerColor=Color(0xFF10101B)){listOf("Главная","Рынок","Мастерская","Склад").forEach{item->NavigationBarItem(selected=tab==item,onClick={tab=item;selected=null},icon={Text(when(item){"Главная"->"⌂";"Рынок"->"⌕";"Мастерская"->"⚒";else->"▣"},fontSize=22.sp,color=if(tab==item)violet else muted)},label={Text(item,fontSize=10.sp)},colors=NavigationBarItemDefaults.colors(indicatorColor=Color(0xFF29203D)))}})}{pad->Column(Modifier.fillMaxSize().background(bg).padding(pad).verticalScroll(rememberScrollState())){
 Header(money,level,xp)
 when(tab){
 "Главная"->{CardBox(Modifier.padding(horizontal=16.dp)){Text("Твой бизнес растёт!",fontSize=19.sp,fontWeight=FontWeight.Bold,color=ink);Text("Покупай выгодно • Ремонтируй • Зарабатывай",color=muted,fontSize=12.sp);Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Stat(stock.size.toString(),"На складе");Stat(sold.toString(),"Продаж");Stat(repairs.toString(),"Ремонтов")}}
 Heading("Быстрые действия");Row(Modifier.padding(horizontal=16.dp),horizontalArrangement=Arrangement.spacedBy(10.dp)){Tile("⌕","Рынок","Ищи выгодные лоты",Modifier.weight(1f)){tab="Рынок"};Tile("⚒","Мастерская","Проверяй и чини",Modifier.weight(1f)){tab="Мастерская"}}
 Heading("Модели телефонов");LazyRow(contentPadding=PaddingValues(horizontal=16.dp),horizontalArrangement=Arrangement.spacedBy(10.dp)){items(catalog.take(5)){m->CardBox(Modifier.width(140.dp)){PhoneArt(m.name,m.color,Modifier.fillMaxWidth().height(110.dp));Text(m.name,color=ink,fontWeight=FontWeight.Bold);Text("Рынок "+m.market+" ₽",color=muted,fontSize=12.sp)}}}
 Heading("Событие");CardBox(Modifier.padding(horizontal=16.dp)){Text(note,color=ink);Text("Прогресс сохраняется на устройстве автоматически.",color=muted,fontSize=12.sp)}}
 "Рынок"->{Heading("Свежие объявления");Text("Поторгуйся и покупай ниже средней цены.",color=muted,modifier=Modifier.padding(horizontal=16.dp));listings.forEachIndexed{idx,l->CardBox(Modifier.padding(horizontal=16.dp,vertical=6.dp)){Row(verticalAlignment=Alignment.CenterVertically){PhoneArt(l.name,l.color,Modifier.width(86.dp).height(120.dp));Column(Modifier.weight(1f)){Text(l.name,color=ink,fontWeight=FontWeight.Bold,fontSize=17.sp);Text("Состояние "+l.condition+"%",color=muted,fontSize=12.sp);Text("Цена "+l.price+" ₽",color=ink);Text("Рынок "+l.market+" ₽",color=green,fontSize=12.sp);Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){OutlinedButton(onClick={val cut=Random.nextInt(500,2001);listings=listings.toMutableList().also{it[idx]=l.copy(price=(l.price-cut).coerceAtLeast(1000))};note="Продавец уступил "+cut+" ₽!"},contentPadding=PaddingValues(horizontal=8.dp)){Text("Торг")};Button(onClick={if(money>=l.price){money-=l.price;val ph=Phone(System.currentTimeMillis().toInt(),l.name,l.condition,l.price,l.market,l.color);stock=stock+ph;selected=ph;checked=setOf();note=l.name+" куплен. Проверь его в мастерской.";listings=listings.toMutableList().also{it[idx]=catalog.random()};persist()}else note="Не хватает денег.",contentPadding=PaddingValues(horizontal=10.dp)){Text("Купить")}}}}}}}}
 "Мастерская"->{Heading("Мини-игра: диагностика");Text("Нажми на каждый узел и проверь состояние.",color=muted,modifier=Modifier.padding(horizontal=16.dp));val ph=selected?:stock.firstOrNull();if(ph==null)CardBox(Modifier.padding(16.dp)){Text("Сначала купи телефон на рынке.",color=ink);Button(onClick={tab="Рынок"}){Text("Открыть рынок")}}else CardBox(Modifier.padding(horizontal=16.dp)){PhoneArt(ph.name,ph.color,Modifier.fillMaxWidth().height(150.dp));Text(ph.name,color=ink,fontSize=20.sp,fontWeight=FontWeight.Bold);Text("Состояние "+ph.condition+"% • закупка "+ph.buy+" ₽",color=muted);listOf("Экран","Батарея","Камеры","Динамик").forEach{part->Row(Modifier.fillMaxWidth().clip(RoundedCornerShape(12.dp)).background(Color(0xFF242237)).clickable{checked=checked+part;note="Проверено: "+part}.padding(12.dp),verticalAlignment=Alignment.CenterVertically){Text(if(part in checked)"✓" else "○",color=violet);Spacer(Modifier.width(10.dp));Text(part,color=ink);Spacer(Modifier.weight(1f));Text(if(part in checked)"Готово" else "Проверить",color=muted,fontSize=12.sp)}};Text("Проверено "+checked.size+"/4",color=muted)
 Button(onClick={if(checked.size<4)note="Проверь все детали сначала." else if(money<3500)note="Нужно 3 500 ₽." else{money-=3500;repairs++;val fixed=ph.copy(condition=(ph.condition+15).coerceAtMost(100),market=ph.market+6000,fixed=true);stock=stock.map{if(it.id==ph.id)fixed else it};selected=fixed;note="Ремонт завершён! Стоимость выросла.";xp+=25;persist()}},modifier=Modifier.fillMaxWidth()){Text("Починить за 3 500 ₽")}
 OutlinedButton(onClick={if(checked.size<4)note="Сначала диагностика." else{val price=ph.market*ph.condition/100;money+=price;sold++;stock=stock.filterNot{it.id==ph.id};selected=null;note=ph.name+" продан за "+price+" ₽. Прибыль "+(price-ph.buy)+" ₽";xp+=40;checked=setOf();persist();tab="Склад"},modifier=Modifier.fillMaxWidth()){Text("Продать за "+(ph.market*ph.condition/100)+" ₽")}}}
 else->{Heading("Склад • "+stock.size+" телефонов");if(stock.isEmpty())CardBox(Modifier.padding(16.dp)){Text("Склад пока пуст.",color=ink);Button(onClick={tab="Рынок"}){Text("На рынок")}};stock.forEach{ph->CardBox(Modifier.padding(horizontal=16.dp,vertical=6.dp).clickable{selected=ph;checked=setOf();tab="Мастерская"}){Row(verticalAlignment=Alignment.CenterVertically){PhoneArt(ph.name,ph.color,Modifier.width(82.dp).height(105.dp));Column(Modifier.weight(1f)){Text(ph.name,color=ink,fontWeight=FontWeight.Bold);Text("Состояние "+ph.condition+"%",color=muted);Text("Закупка "+ph.buy+" ₽",color=muted,fontSize=12.sp);Text("Оценка "+ph.market+" ₽",color=green);Text(if(ph.fixed)"После ремонта" else "Нужна проверка",color=violet,fontSize=12.sp)}}}}
 }
 Spacer(Modifier.height(20.dp))
 }}}
}
@Composable private fun Header(money:Int,level:Int,xp:Int){Column(Modifier.fillMaxWidth().padding(18.dp)){Row(verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(52.dp).clip(RoundedCornerShape(15.dp)).background(Brush.linearGradient(listOf(violet,Color(0xFF16D6E9)))),contentAlignment=Alignment.Center){Text("↗",fontSize=30.sp,color=ink)};Spacer(Modifier.width(10.dp));Column(Modifier.weight(1f)){Text("Перекуп Pro",fontSize=22.sp,fontWeight=FontWeight.ExtraBold,color=ink);Text("Симулятор телефонов",color=muted);Text("v0.1 • Игровая версия",color=muted,fontSize=10.sp)}};Spacer(Modifier.height(12.dp));Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Surface(color=panel,shape=RoundedCornerShape(14.dp),modifier=Modifier.weight(1f)){Text("◉  "+money+" ₽",color=Color(0xFFFFD35C),fontWeight=FontWeight.Bold,fontSize=18.sp,modifier=Modifier.padding(12.dp))};Surface(color=panel,shape=RoundedCornerShape(14.dp)){Text("★ Ур. "+level,color=ink,fontWeight=FontWeight.Bold,modifier=Modifier.padding(12.dp))}};LinearProgressIndicator(progress={(xp/(level*100f)).coerceIn(0f,1f)},modifier=Modifier.fillMaxWidth().padding(top=8.dp).height(5.dp),color=violet,trackColor=panel)}}
@Composable private fun Heading(t:String){Row(Modifier.fillMaxWidth().padding(start=18.dp,end=18.dp,top=22.dp,bottom=10.dp),verticalAlignment=Alignment.CenterVertically){Box(Modifier.width(4.dp).height(22.dp).clip(CircleShape).background(violet));Spacer(Modifier.width(10.dp));Text(t,color=ink,fontSize=19.sp,fontWeight=FontWeight.Bold)}}
@Composable private fun CardBox(modifier:Modifier=Modifier,content:@Composable ColumnScope.()->Unit){Column(modifier.fillMaxWidth().clip(RoundedCornerShape(20.dp)).background(Brush.linearGradient(listOf(Color(0xFF1D1B30),panel))).border(1.dp,Color(0xFF302B49),RoundedCornerShape(20.dp)).padding(14.dp),verticalArrangement=Arrangement.spacedBy(8.dp),content=content)}
@Composable private fun Stat(value:String,label:String){Column(Modifier.weight(1f).clip(RoundedCornerShape(12.dp)).background(Color(0xFF242237)).padding(10.dp),horizontalAlignment=Alignment.Center){Text(value,color=ink,fontWeight=FontWeight.Bold,fontSize=18.sp);Text(label,color=muted,fontSize=10.sp)}}
@Composable private fun Tile(icon:String,title:String,sub:String,modifier:Modifier=Modifier,onClick:()->Unit){Column(modifier.clip(RoundedCornerShape(17.dp)).background(panel).border(1.dp,Color(0xFF302B49),RoundedCornerShape(17.dp)).clickable(onClick=onClick).padding(14.dp)){Text(icon,color=violet,fontSize=28.sp);Text(title,color=ink,fontWeight=FontWeight.Bold);Text(sub,color=muted,fontSize=12.sp)}}
@Composable private fun PhoneArt(name:String,color:Int,modifier:Modifier=Modifier){Box(modifier,contentAlignment=Alignment.Center){Box(Modifier.width(62.dp).fillMaxHeight(.88f).clip(RoundedCornerShape(14.dp)).background(Color(0xFF05050A)).border(2.dp,Color(0xFF55546A),RoundedCornerShape(14.dp)).padding(5.dp)){Box(Modifier.fillMaxSize().clip(RoundedCornerShape(10.dp)).background(Brush.linearGradient(listOf(Color(color),Color(color).copy(alpha=.35f),Color(0xFF11111C))))){Column(Modifier.align(Alignment.TopStart).padding(6.dp),verticalArrangement=Arrangement.spacedBy(3.dp)){Row(horizontalArrangement=Arrangement.spacedBy(3.dp)){repeat(3){Box(Modifier.size(8.dp).clip(CircleShape).background(Color(0xFF080811)))}};Box(Modifier.width(18.dp).height(4.dp).clip(CircleShape).background(Color.White.copy(alpha=.4f)))};Text("✦",Modifier.align(Alignment.Center),color=ink.copy(alpha=.65f),fontSize=24.sp);Text(name.take(1),Modifier.align(Alignment.BottomEnd).padding(6.dp),color=ink,fontWeight=FontWeight.Bold,fontSize=10.sp)}}}
